/**
 * Turns prompts/**\/*.md into src/lib/prompts.generated.ts: every prompt's frontmatter, body, the
 * {{variables}} its body uses, and a content hash. The app imports prompts from there, so a wrong
 * prompt name or a missing variable fails `npm run typecheck` instead of a live request.
 *
 *   npm run prompts   # also runs before dev, build, typecheck and test
 *
 * In `next dev`, next.config.ts re-runs it whenever a prompt file changes. The generated file is
 * committed (so a fresh checkout typechecks), and a test fails if it's out of date.
 */
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const PROMPTS_DIR = path.join(ROOT, "prompts");
const OUT = path.join(ROOT, "src", "lib", "prompts.generated.ts");

/** `key: value` frontmatter lines + body. */
function parse(raw: string): { meta: Record<string, string>; body: string } {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return { meta: {}, body: raw.trim() };
  const meta: Record<string, string> = {};
  for (const line of match[1].split("\n")) {
    const i = line.indexOf(":");
    if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return { meta, body: match[2].trim() };
}

function files(dir: string, prefix = ""): string[] {
  return readdirSync(dir, { withFileTypes: true })
    .sort((a, b) => a.name.localeCompare(b.name))
    .flatMap((e) => (e.isDirectory() ? files(path.join(dir, e.name), `${prefix}${e.name}/`) : e.name.endsWith(".md") ? [`${prefix}${e.name}`] : []));
}

/** The generated module's source for the current prompts/ folder. */
export function buildPromptsModule(): string {
  const entries = files(PROMPTS_DIR).map((file) => {
    const { meta, body } = parse(readFileSync(path.join(PROMPTS_DIR, file), "utf8"));
    const vars = [...new Set([...body.matchAll(/\{\{(\w+)\}\}/g)].map((m) => m[1]))].sort();
    const hash = createHash("sha256").update(JSON.stringify({ meta, body })).digest("hex").slice(0, 12);
    return { name: file.replace(/\.md$/, ""), meta, body, vars, hash };
  });
  const lines = [
    "// Generated by scripts/gen-prompts.ts from prompts/**/*.md. Do not edit; run `npm run prompts`.",
    "export const PROMPTS = {",
    ...entries.map(
      (e) =>
        `  ${JSON.stringify(e.name)}: {\n    meta: ${JSON.stringify(e.meta)},\n    vars: ${JSON.stringify(e.vars)},\n    hash: ${JSON.stringify(e.hash)},\n    body: ${JSON.stringify(e.body)},\n  },`,
    ),
    "} as const;",
    "",
  ];
  return lines.join("\n");
}

export const GENERATED_PATH = OUT;

/** Writes the module; returns true if it changed. */
export function generatePrompts(): boolean {
  const next = buildPromptsModule();
  let prev = "";
  try {
    prev = readFileSync(OUT, "utf8");
  } catch {
    /* first run */
  }
  if (prev === next) return false;
  writeFileSync(OUT, next);
  return true;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const changed = generatePrompts();
  console.log(changed ? "prompts: wrote src/lib/prompts.generated.ts" : "prompts: up to date");
}
